CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON session(user_id);
CREATE TABLE account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX account_user_idx ON account(user_id);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE members (user_id TEXT PRIMARY KEY REFERENCES user(id), seat INTEGER NOT NULL UNIQUE CHECK(seat IN (0,1)), color TEXT NOT NULL, avatar_id TEXT);
CREATE TABLE settings (id TEXT PRIMARY KEY, name TEXT NOT NULL, subtitle TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE assets (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), mime TEXT NOT NULL, filename TEXT NOT NULL, size INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE entries (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('movie','book')), title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', cover_id TEXT REFERENCES assets(id), links TEXT NOT NULL DEFAULT '[]', tags TEXT NOT NULL DEFAULT '[]', pinned INTEGER NOT NULL DEFAULT 0, is_next INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX entry_kind_idx ON entries(kind,deleted_at);
CREATE TABLE movies (entry_id TEXT PRIMARY KEY REFERENCES entries(id) ON DELETE CASCADE, director TEXT NOT NULL DEFAULT '', year INTEGER, status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','completed')), completed_at INTEGER);
CREATE TABLE books (entry_id TEXT PRIMARY KEY REFERENCES entries(id) ON DELETE CASCADE, author TEXT NOT NULL DEFAULT '', year INTEGER);
CREATE TABLE reading_progress (entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id), status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','completed')), completed_at INTEGER, revision INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX reading_unique ON reading_progress(entry_id,user_id);
CREATE TABLE reviews (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES user(id), rating REAL CHECK(rating IS NULL OR (rating >= 0.5 AND rating <= 5 AND rating*2=CAST(rating*2 AS INTEGER))), body TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX review_unique ON reviews(entry_id,user_id);
CREATE TABLE memories (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE, date TEXT, place TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, photos TEXT NOT NULL DEFAULT '[]', revision INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX memory_entry_idx ON memories(entry_id);
CREATE TABLE challenges (id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL, target INTEGER NOT NULL, achieved_at INTEGER);
CREATE TABLE challenge_entries (challenge_id TEXT NOT NULL REFERENCES challenges(id), entry_id TEXT NOT NULL REFERENCES entries(id) ON DELETE CASCADE);
CREATE UNIQUE INDEX challenge_entry_unique ON challenge_entries(challenge_id,entry_id);
